.studio .neatlogs-page .nl-select { position: relative; display: block; width: 126px; }
.studio .neatlogs-page .nl-select select { appearance: none; padding: 0 26px 0 9px; }
.studio .neatlogs-page .nl-select .nl-icon { position: absolute; top: 9px; right: 8px; color: var(--text-3); pointer-events: none; }
.studio .neatlogs-page .nl-segments { display: flex; gap: 2px; margin-left: auto; padding: 2px; border: 1px solid var(--line); border-radius: 7px; background: var(--bg); }
.studio .neatlogs-page .nl-segments button { height: 24px; padding: 0 8px; border: 0; border-radius: 5px; background: transparent; color: var(--text-3); font-size: 10.5px; }
.studio .neatlogs-page .nl-segments button:hover { color: var(--text); }
