@media (max-width: 850px) {
  .studio .neatlogs-page { padding: 22px 18px 32px; }
  .studio .neatlogs-page .nl-kpis { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .studio .neatlogs-page .nl-kpis article:nth-child(3) { border-left: 0; }
  .studio .neatlogs-page .nl-kpis article:nth-child(n+3) { border-top: 1px solid var(--line); }
  .studio .neatlogs-page .nl-segments { width: 100%; margin-left: 0; overflow-x: auto; }
  .studio .neatlogs-page .nl-segments button { flex: 1; }
  .studio .neatlogs-page .nl-tv-stats { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .studio .neatlogs-page .nl-tv-stats > div:nth-child(3) { padding-left: 22px; border-left: 0; }
  .studio .neatlogs-page .nl-tv-stats > div:nth-child(n+3) { border-top: 1px solid var(--line); }
}
@media (max-width: 560px) {
  .studio .neatlogs-page .nl-header { align-items: flex-start; flex-direction: column; }
  .studio .neatlogs-page .nl-connection-detail { margin-left: 0; }
  .studio .neatlogs-page .nl-kpis { grid-template-columns: 1fr; }
  .studio .neatlogs-page .nl-kpis article + article { border-top: 1px solid var(--line); border-left: 0; }
  .studio .neatlogs-page .nl-browser-head { align-items: flex-start; flex-direction: column; padding-top: 12px; padding-bottom: 12px; }
  .studio .neatlogs-page .nl-search { max-width: none; }
  .studio .neatlogs-page :is(.nl-span-type, .nl-span-usage) { display: none; }
}

toolu_01H3ar1hweE2GkMcv3WjQsUu.content:
.studio .neatlogs-page {
  display: block;
  --nl-cyan: #78c5d6;
  --nl-cyan-soft: rgba(79, 184, 208, 0.12);
  --nl-workflow: #a78bfa;
  --nl-tool: #8b93ff;
  --nl-llm: #e8875a;
  --nl-sunk: #111215;
  --nl-tree-line: rgba(255, 255, 255, 0.11);
  padding: 30px 32px 42px;
}
.studio .neatlogs-page .nl-icon { fill: none; stroke: currentColor; stroke-width: 1.55; stroke-linecap: round; stroke-linejoin: round; }
.studio .neatlogs-page button, .studio .neatlogs-page input, .studio .neatlogs-page select { font: inherit; }
.studio .neatlogs-page .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.studio .neatlogs-page :is(button, input, select):focus-visible { outline: 2px solid var(--nl-cyan); outline-offset: 2px; }
.studio .neatlogs-page :is(.nl-header, .nl-heading, .nl-connection, .nl-browser-head, .nl-browser-head > div, .nl-toolbar) { display: flex; align-items: center; }
.studio .neatlogs-page .nl-header { justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.studio .neatlogs-page .nl-heading { gap: 12px; }
.studio .neatlogs-page .nl-mark { display: grid; place-items: center; width: 36px; height: 36px; border: 1px solid var(--line-strong); border-radius: 9px; background: linear-gradient(145deg, #25272d, #141519); box-shadow: 0 1px 0 rgba(255,255,255,.08) inset, 0 6px 18px rgba(0,0,0,.18); color: #f4f4f5; font-size: 16px; font-weight: 650; }
.studio .neatlogs-page .nl-heading h1 { font-size: 22px; font-weight: 620; letter-spacing: -.025em; }
.studio .neatlogs-page .nl-heading p { margin-top: 3px; color: var(--text-3); font-size: 12.5px; }
.studio .neatlogs-page .nl-connection { gap: 8px; height: 28px; padding: 0 10px; border: 1px solid var(--line); border-radius: 999px; background: var(--panel); color: var(--text-2); font-size: 11.5px; white-space: nowrap; }
.studio .neatlogs-page :is(.nl-connection i, .nl-trace-status i, .nl-outcome i) { flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--text-3); }
.studio .neatlogs-page .nl-connection.connected i { background: var(--good); }
.studio .neatlogs-page .nl-connection.unreachable i { background: var(--bad); }
.studio .neatlogs-page .nl-connection.loading i { background: var(--warn); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-connection-detail { margin: -7px 0 18px 48px; color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page .nl-connection-detail.unreachable { color: var(--bad-text); }

.studio .neatlogs-page .nl-kpis { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); margin-bottom: 16px; border: 1px solid var(--line); border-radius: 11px; background: var(--panel); overflow: hidden; }
.studio .neatlogs-page .nl-kpis article { min-width: 0; padding: 17px 18px 16px; }
.studio .neatlogs-page .nl-kpis article + article { border-left: 1px solid var(--line); }
.studio .neatlogs-page .nl-kpis span { display: block; color: var(--text-2); font-size: 11.5px; }
.studio .neatlogs-page .nl-kpis strong { display: block; margin: 6px 0 3px; color: var(--text); font-size: 22px; font-weight: 570; letter-spacing: -.025em; }
.studio .neatlogs-page .nl-kpis small { color: var(--text-3); font-size: 11px; }

.studio .neatlogs-page :is(.nl-browser, .nl-rail, .nl-trace-view) { min-width: 0; border: 1px solid var(--line); border-radius: 11px; background: var(--panel); overflow: hidden; }
.studio .neatlogs-page .nl-browser-head { justify-content: space-between; gap: 16px; min-height: 57px; padding: 0 14px 0 17px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-browser-head > div { gap: 8px; }
.studio .neatlogs-page .nl-browser-head h2 { font-size: 13.5px; font-weight: 600; }
.studio .neatlogs-page .nl-browser-head span { color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page :is(.nl-check-button, .nl-button, .nl-lookup-message button, .nl-filter-empty button) { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 30px; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 7px; background: var(--raised); color: var(--text-2); font-size: 11.5px; }
.studio .neatlogs-page :is(.nl-check-button, .nl-button, .nl-lookup-message button, .nl-filter-empty button):hover:not(:disabled) { border-color: rgba(255,255,255,.18); background: var(--hover); color: var(--text); }
.studio .neatlogs-page .nl-check-button:disabled { opacity: .46; }
.studio .neatlogs-page .nl-check-button:not(:disabled) .nl-icon { color: var(--nl-cyan); }
.studio .neatlogs-page .nl-icon-button { display: inline-grid; flex: none; place-items: center; width: 30px; height: 30px; padding: 0; border: 1px solid var(--line-strong); border-radius: 7px; background: var(--raised); color: var(--text-2); }
.studio .neatlogs-page .nl-icon-button:hover:not(:disabled) { background: var(--hover); color: var(--text); }
.studio .neatlogs-page .nl-icon-button:disabled { opacity: .5; }
.studio .neatlogs-page .nl-icon-button:disabled .nl-icon { animation: nl-spin .8s linear infinite; }
.studio .neatlogs-page .nl-icon-button.small { width: 22px; height: 22px; border: 0; background: transparent; color: var(--text-3); }

.studio .neatlogs-page .nl-toolbar { flex-wrap: wrap; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--line); background: rgba(0,0,0,.08); }
.studio .neatlogs-page .nl-search { position: relative; display: flex; flex: 1 1 180px; align-items: center; min-width: 145px; max-width: 260px; color: var(--text-3); }
.studio .neatlogs-page .nl-search .nl-icon { position: absolute; left: 9px; pointer-events: none; }
.studio .neatlogs-page :is(.nl-search input, .nl-select select) { width: 100%; height: 30px; border: 1px solid var(--line); border-radius: 7px; background: var(--bg); color: var(--text); font-size: 11.5px; }
.studio .neatlogs-page .nl-search input { padding: 0 10px 0 30px; }
.studio .neatlogs-page .nl-search input::placeholder { color: var(--text-3); }
.studio .neatlogs-page .nl-select { position: relative; display: block; width: 126px; }
.studio .neatlogs-page .nl-select select { appearance: none; padding: 0 26px 0 9px; }
.studio .neatlogs-page .nl-select .nl-icon { position: absolute; top: 9px; right: 8px; color: var(--text-3); pointer-events: none; }
.studio .neatlogs-page .nl-segments { display: flex; gap: 2px; margin-left: auto; padding: 2px; border: 1px solid var(--line); border-radius: 7px; background: var(--bg); }
.studio .neatlogs-page .nl-segments button { height: 24px; padding: 0 8px; border: 0; border-radius: 5px; background: transparent; color: var(--text-3); font-size: 10.5px; }
.studio .neatlogs-page .nl-segments button:hover { color: var(--text); }
.studio .neatlogs-page .nl-segments button.active { background: var(--raised); color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,.25); }

.studio .neatlogs-page .nl-table-scroll { overflow-x: auto; }
.studio .neatlogs-page .nl-table { width: 100%; min-width: 650px; border-collapse: collapse; table-layout: fixed; }
.studio .neatlogs-page .nl-table th { height: 31px; padding: 0 12px; border-bottom: 1px solid var(--line); color: var(--text-3); font-size: 10px; font-weight: 520; letter-spacing: .035em; text-align: left; text-transform: uppercase; }
.studio .neatlogs-page .nl-table th:first-child { width: 35%; padding-left: 17px; }
.studio .neatlogs-page .nl-table th:nth-child(2) { width: 18%; }
.studio .neatlogs-page .nl-table th:nth-child(3) { width: 12%; }
.studio .neatlogs-page .nl-table th:nth-child(4) { width: 11%; }
.studio .neatlogs-page .nl-table th:nth-child(5) { width: 18%; }
.studio .neatlogs-page .nl-table th:nth-child(6) { width: 6%; }
.studio .neatlogs-page .nl-table :is(th,td).num { text-align: right; }
.studio .neatlogs-page .nl-table td { height: 48px; padding: 0 12px; border-bottom: 1px solid var(--line); color: var(--text-2); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.studio .neatlogs-page .nl-table tbody tr:last-child td { border-bottom: 0; }
.studio .neatlogs-page .nl-table tbody tr { cursor: pointer; transition: background .1s; }
.studio .neatlogs-page .nl-table tbody tr:hover { background: rgba(255,255,255,.025); }
.studio .neatlogs-page .nl-table td:first-child { padding: 0; }
.studio .neatlogs-page .nl-table td.nl-open { color: var(--text-3); opacity: 0; text-align: right; transition: opacity .12s, transform .12s; }
.studio .neatlogs-page .nl-table tbody tr:hover td.nl-open { color: var(--nl-cyan); opacity: 1; transform: translateX(2px); }
.studio .neatlogs-page .nl-session-button { display: flex; flex-direction: column; justify-content: center; width: 100%; height: 48px; padding: 0 12px 0 17px; border: 0; background: transparent; color: var(--text-3); font-size: 10.5px; text-align: left; overflow: hidden; }
.studio .neatlogs-page .nl-session-button:focus-visible { outline-offset: -3px; }
.studio .neatlogs-page .nl-session-name { display: block; width: 100%; margin-bottom: 2px; color: var(--text); font-size: 12px; font-weight: 540; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.studio .neatlogs-page .nl-model { color: var(--text-3); font-family: var(--mono); font-size: 10.5px; }
.studio .neatlogs-page :is(.nl-trace-status, .nl-outcome) { display: inline-flex; align-items: center; gap: 6px; color: var(--text-3); font-size: 10.5px; }
.studio .neatlogs-page .nl-trace-status.matched { color: var(--good-text); }
.studio .neatlogs-page .nl-trace-status.matched i { background: var(--good); }
.studio .neatlogs-page .nl-trace-status.error { color: var(--bad-text); }
.studio .neatlogs-page .nl-trace-status.error i { background: var(--bad); }
.studio .neatlogs-page .nl-trace-status.loading { color: var(--nl-cyan); }
.studio .neatlogs-page .nl-trace-status.loading i { background: var(--nl-cyan); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-trace-status.none i { background: var(--warn); }
.studio .neatlogs-page .nl-trace-status.missing i { background: transparent; border: 1px solid var(--text-3); }

.studio .neatlogs-page .nl-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 34px 28px; text-align: center; }
.studio .neatlogs-page .nl-empty :is(h2,h3) { color: var(--text); font-size: 14px; font-weight: 580; }
.studio .neatlogs-page .nl-empty p { max-width: 245px; margin-top: 7px; color: var(--text-3); font-size: 11.5px; line-height: 1.55; }
.studio .neatlogs-page .nl-filter-empty { min-height: 250px; }
.studio .neatlogs-page .nl-filter-empty > .nl-icon { margin-bottom: 12px; color: var(--text-3); }
.studio .neatlogs-page .nl-filter-empty button { margin-top: 15px; }

.studio .neatlogs-page .nl-outcome { height: 20px; padding: 0 8px; border-radius: 999px; background: var(--raised); font-weight: 500; letter-spacing: 0; }
.studio .neatlogs-page .nl-outcome.complete { color: var(--good-text); background: var(--good-soft); }
.studio .neatlogs-page .nl-outcome.complete i { background: var(--good); }
.studio .neatlogs-page .nl-outcome.failed { color: var(--bad-text); background: var(--bad-soft); }
.studio .neatlogs-page .nl-outcome.failed i { background: var(--bad); }
.studio .neatlogs-page .nl-outcome.running { color: var(--accent); background: var(--accent-soft); }
.studio .neatlogs-page .nl-outcome.running i { background: var(--accent); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-session-error { padding: 10px 12px; border: 1px solid rgba(229,72,77,.25); border-radius: 9px; background: var(--bad-soft); color: var(--bad-text); font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }
.studio .neatlogs-page .nl-loading { display: flex; align-items: center; justify-content: center; gap: 10px; min-height: 120px; border: 1px dashed var(--line-strong); border-radius: 12px; color: var(--text-3); font-size: 12px; }
.studio .neatlogs-page .nl-loading i { width: 14px; height: 14px; border: 1.5px solid var(--line-strong); border-top-color: var(--nl-cyan); border-radius: 50%; animation: nl-spin .8s linear infinite; }
.studio .neatlogs-page .nl-lookup-message { padding: 16px 18px; border: 1px solid var(--line); border-radius: 12px; background: var(--nl-sunk); }
.studio .neatlogs-page .nl-lookup-message.error { border-color: rgba(229,72,77,.25); background: var(--bad-soft); }
.studio .neatlogs-page .nl-lookup-message h4 { color: var(--text); font-size: 12.5px; font-weight: 570; }
.studio .neatlogs-page .nl-lookup-message.error h4 { color: var(--bad-text); }
.studio .neatlogs-page .nl-lookup-message p { margin-top: 5px; color: var(--text-3); font-size: 11.5px; line-height: 1.5; overflow-wrap: anywhere; }
.studio .neatlogs-page .nl-lookup-message button { margin-top: 12px; height: 28px; background: var(--panel); }
.studio .neatlogs-page .nl-inline-error { padding: 8px 10px; border-radius: 7px; background: var(--bad-soft); color: var(--bad-text); font-size: 11px; line-height: 1.45; }

/* Focus mode: a session rail beside the full trace */
.studio .neatlogs-page.inspecting { display: flex; flex-direction: column; gap: 0; padding-bottom: 22px; overflow: hidden; }
.studio .neatlogs-page.inspecting .nl-header { margin-bottom: 16px; }
.studio .neatlogs-page.inspecting .nl-connection-detail { margin-top: -9px; margin-bottom: 14px; }
.studio .neatlogs-page.inspecting .nl-focus { display: grid; flex: 1 1 0; grid-template-columns: 264px minmax(0,1fr); gap: 14px; min-height: 0; }

.studio .neatlogs-page .nl-rail { display: flex; flex-direction: column; min-height: 0; }
.studio .neatlogs-page .nl-rail-head { display: flex; align-items: center; justify-content: space-between; height: 48px; padding: 0 12px 0 8px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-rail-head > span { display: grid; place-items: center; min-width: 22px; height: 20px; padding: 0 6px; border-radius: 999px; background: var(--raised); color: var(--text-3); font-size: 10px; }
.studio .neatlogs-page .nl-back { display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 9px; border: 0; border-radius: 7px; background: transparent; color: var(--text-2); font-size: 12px; font-weight: 520; }
.studio .neatlogs-page .nl-back:hover { background: var(--hover); color: var(--text); }
.studio .neatlogs-page .nl-rail-search { padding: 10px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-rail-search .nl-search { max-width: none; }
.studio .neatlogs-page .nl-rail-list { flex: 1; min-height: 0; margin: 0; padding: 6px; overflow-y: auto; list-style: none; }
.studio .neatlogs-page .nl-rail-list button { display: flex; flex-direction: column; gap: 4px; width: 100%; padding: 9px 10px; border: 0; border-radius: 8px; background: transparent; color: var(--text-3); font-size: 10.5px; text-align: left; }
.studio .neatlogs-page .nl-rail-list button:hover { background: rgba(255,255,255,.03); }
.studio .neatlogs-page .nl-rail-list button.active { background: var(--nl-cyan-soft); box-shadow: 2px 0 0 var(--nl-cyan) inset; }
.studio .neatlogs-page .nl-rail-name { display: flex; justify-content: space-between; gap: 8px; color: var(--text); font-size: 12px; font-weight: 540; }
.studio .neatlogs-page .nl-rail-name time { flex: none; color: var(--text-3); font-family: var(--mono); font-size: 10px; font-weight: 400; }
.studio .neatlogs-page .nl-rail-meta { display: flex; align-items: center; gap: 7px; min-width: 0; white-space: nowrap; }
.studio .neatlogs-page .nl-rail-empty { padding: 16px 10px; color: var(--text-3); font-size: 11.5px; line-height: 1.6; }
.studio .neatlogs-page .nl-rail-empty button { padding: 0; border: 0; background: none; color: var(--nl-cyan); }

.studio .neatlogs-page .nl-trace-view { display: flex; flex-direction: column; min-height: 0; }
.studio .neatlogs-page .nl-tv-head { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 15px 18px 14px 22px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-tv-title { min-width: 0; }
.studio .neatlogs-page .nl-crumbs { display: block; color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page .nl-crumbs i { margin: 0 7px; color: #4b4f57; font-style: normal; }
.studio .neatlogs-page .nl-tv-title h2 { display: flex; align-items: center; gap: 10px; margin-top: 4px; color: var(--text); font-size: 18px; font-weight: 600; letter-spacing: -.02em; }
.studio .neatlogs-page .nl-live { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 999px; background: var(--nl-cyan-soft); color: var(--nl-cyan); font-size: 10.5px; font-weight: 500; letter-spacing: 0; }
.studio .neatlogs-page .nl-tv-actions { display: flex; flex: none; align-items: center; gap: 8px; }

.studio .neatlogs-page .nl-tv-stats { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)) minmax(0,1.6fr); margin: 0; border-bottom: 1px solid var(--line); background: rgba(0,0,0,.1); }
.studio .neatlogs-page .nl-tv-stats > div { min-width: 0; padding: 12px 18px 13px 22px; }
.studio .neatlogs-page .nl-tv-stats > div + div { border-left: 1px solid var(--line); padding-left: 18px; }
.studio .neatlogs-page .nl-tv-stats dt { color: var(--text-3); font-size: 9.5px; font-weight: 520; letter-spacing: .06em; text-transform: uppercase; }
.studio .neatlogs-page .nl-tv-stats dd { display: flex; align-items: center; gap: 4px; min-width: 0; margin: 5px 0 2px; color: var(--text); font-size: 15px; font-weight: 570; letter-spacing: -.01em; }
.studio .neatlogs-page .nl-tv-stats small { display: block; color: var(--text-3); font-size: 10.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.studio .neatlogs-page .nl-tv-session code { min-width: 0; color: var(--text-2); font-family: var(--mono); font-size: 11px; font-weight: 400; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.studio .neatlogs-page .nl-tv-body { display: flex; flex: 1; flex-direction: column; gap: 22px; min-height: 0; padding: 24px 28px 36px; overflow-y: auto; }
.studio .neatlogs-page .nl-tv-body > * { flex-shrink: 0; width: 100%; max-width: 980px; margin: 0 auto; }
.studio .neatlogs-page .nl-eyebrow { display: block; margin-bottom: 8px; color: var(--text-3); font-size: 9.5px; font-weight: 560; letter-spacing: .09em; text-transform: uppercase; }
.studio .neatlogs-page .nl-eyebrow.out { color: #c9a27e; }

/* Input bubble, right-aligned like the Neatlogs conversation view */
.studio .neatlogs-page .nl-brief-wrap { display: flex; justify-content: flex-end; }
.studio .neatlogs-page .nl-brief { position: relative; max-width: min(640px, 88%); padding: 14px 17px 13px; border: 1px solid var(--line-strong); border-radius: 14px 14px 4px 14px; background: #1b1c21; box-shadow: 0 10px 30px rgba(0,0,0,.18); }
.studio .neatlogs-page .nl-brief .prose { font-size: 12.5px; line-height: 1.6; }
.studio .neatlogs-page .nl-brief.clamped { max-height: 196px; overflow: hidden; }
.studio .neatlogs-page .nl-brief.clamped::after { content: ""; position: absolute; right: 0; bottom: 0; left: 0; height: 70px; background: linear-gradient(rgba(27,28,33,0), #1b1c21 72%); pointer-events: none; }
.studio .neatlogs-page .nl-more { margin-top: 9px; padding: 0; border: 0; background: none; color: var(--nl-tool); font-size: 10px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; }
.studio .neatlogs-page .nl-more:hover { color: #b3b8ff; }
.studio .neatlogs-page .nl-brief.clamped .nl-more { position: absolute; bottom: 11px; left: 17px; z-index: 1; margin: 0; }
.studio .neatlogs-page .nl-brief-checks { display: grid; gap: 8px; margin: 0; padding: 0; list-style: none; }
.studio .neatlogs-page .nl-brief-checks li { display: grid; grid-template-columns: auto minmax(0,1fr); align-items: baseline; gap: 10px; color: var(--text-2); font-size: 12px; line-height: 1.5; }
.studio .neatlogs-page :is(.nl-brief-checks, .nl-verdict) code { padding: 1px 6px; border-radius: 4px; background: var(--raised); color: var(--text); font-family: var(--mono); font-size: 10.5px; white-space: nowrap; }

/* Step tree */
.studio .neatlogs-page .nl-steps { border: 1px solid var(--line); border-radius: 12px; background: var(--nl-sunk); box-shadow: 0 1px 0 rgba(255,255,255,.03) inset; }
.studio .neatlogs-page .nl-steps.empty { padding: 18px; color: var(--text-3); font-size: 12px; }
.studio .neatlogs-page .nl-steps-head { display: flex; align-items: center; gap: 14px; height: 42px; padding: 0 12px 0 10px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-steps-toggle { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 6px; border: 0; border-radius: 6px; background: transparent; color: var(--text-2); font-size: 10.5px; font-weight: 560; letter-spacing: .07em; text-transform: uppercase; }
.studio .neatlogs-page .nl-steps-toggle:hover { background: rgba(255,255,255,.04); color: var(--text); }
.studio .neatlogs-page .nl-steps-toggle .nl-icon { transition: transform .15s; }
.studio .neatlogs-page .nl-steps-toggle[aria-expanded="false"] .nl-icon { transform: rotate(-90deg); }
.studio .neatlogs-page .nl-steps-counts { display: flex; gap: 12px; font-size: 10.5px; }
.studio .neatlogs-page .nl-steps-counts b { font-weight: 500; }
.studio .neatlogs-page .nl-steps-counts .llm { color: var(--nl-llm); }
.studio .neatlogs-page .nl-steps-counts .tool { color: var(--nl-tool); }
.studio .neatlogs-page .nl-steps-counts .failed { color: var(--bad-text); }
.studio .neatlogs-page .nl-ghost { display: inline-flex; align-items: center; gap: 6px; height: 26px; margin-left: auto; padding: 0 8px; border: 0; border-radius: 6px; background: transparent; color: var(--text-3); font-size: 10px; font-weight: 560; letter-spacing: .07em; text-transform: uppercase; }
.studio .neatlogs-page .nl-ghost:hover { background: rgba(255,255,255,.04); color: var(--text); }
.studio .neatlogs-page .nl-trace-tabs { display: flex; gap: 6px; }
.studio .neatlogs-page .nl-trace-tabs button { display: inline-flex; align-items: center; gap: 7px; height: 28px; padding: 0 11px; border: 1px solid var(--line); border-radius: 999px; background: transparent; color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page .nl-trace-tabs button.active { border-color: var(--line-strong); background: var(--raised); color: var(--text); }
.studio .neatlogs-page .nl-trace-tabs small { color: var(--text-3); font-family: var(--mono); font-size: 10px; }

.studio .neatlogs-page .nl-tree { margin: 0; padding: 8px 14px 10px; list-style: none; }
.studio .neatlogs-page .nl-span { position: relative; --type: var(--nl-cyan); }
.studio .neatlogs-page .nl-span.workflow, .studio .neatlogs-page .nl-span.agent { --type: var(--nl-workflow); }
.studio .neatlogs-page .nl-span.tool { --type: var(--nl-tool); }
.studio .neatlogs-page .nl-span.llm { --type: var(--nl-llm); }
.studio .neatlogs-page .nl-span.failed { --type: var(--bad); }
.studio .neatlogs-page :is(.nl-guide, .nl-tail) { position: absolute; bottom: 0; width: 1px; margin-left: -.5px; background: var(--nl-tree-line); pointer-events: none; }
.studio .neatlogs-page .nl-guide { top: 0; }
.studio .neatlogs-page .nl-tail { top: 25px; }
.studio .neatlogs-page .nl-elbow { position: absolute; top: 0; width: 14px; height: 17px; margin-left: -.5px; border-bottom: 1px solid var(--nl-tree-line); border-left: 1px solid var(--nl-tree-line); border-bottom-left-radius: 7px; pointer-events: none; }
.studio .neatlogs-page .nl-span-row { display: flex; align-items: center; height: 34px; }
.studio .neatlogs-page .nl-span-toggle { position: relative; z-index: 1; display: grid; flex: none; place-items: center; width: 22px; height: 34px; padding: 0; border: 0; background: transparent; }
.studio .neatlogs-page .nl-span-toggle span { display: grid; place-items: center; width: 15px; height: 15px; border: 1px solid rgba(255,255,255,.2); border-radius: 50%; background: var(--nl-sunk); color: var(--text-3); font-family: var(--mono); font-size: 11px; line-height: 1; transition: border-color .12s, color .12s; }
.studio .neatlogs-page .nl-span-toggle:hover span { border-color: var(--text-3); color: var(--text); }
.studio .neatlogs-page .nl-span-main { display: flex; flex: 1; align-items: center; gap: 9px; min-width: 0; height: 30px; margin-left: 6px; padding: 0 8px; border: 0; border-radius: 7px; background: transparent; color: var(--text-2); text-align: left; transition: background .1s; }
.studio .neatlogs-page .nl-span-main:hover { background: rgba(255,255,255,.035); }
.studio .neatlogs-page .nl-span.open > .nl-span-row .nl-span-main { background: rgba(255,255,255,.05); }
.studio .neatlogs-page .nl-span-icon { display: grid; flex: none; place-items: center; color: var(--type); }
.studio .neatlogs-page .nl-span-name { min-width: 0; color: #d9d8d2; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.studio .neatlogs-page .nl-span.workflow .nl-span-name { color: var(--text); font-weight: 560; }
.studio .neatlogs-page .nl-span.failed .nl-span-name { color: var(--bad-text); }
.studio .neatlogs-page .nl-ns { color: var(--text-3); opacity: .75; }
.studio .neatlogs-page .nl-span-type { flex: none; color: var(--type); font-size: 9px; font-weight: 620; letter-spacing: .08em; }
.studio .neatlogs-page .nl-span-usage { flex: none; color: var(--text-3); font-family: var(--mono); font-size: 10px; }
.studio .neatlogs-page .nl-span-bar { position: relative; flex: none; width: 128px; height: 4px; margin: 0 14px 0 10px; border-radius: 2px; background: rgba(255,255,255,.045); }
.studio .neatlogs-page .nl-span-bar i { position: absolute; top: 0; bottom: 0; min-width: 2px; border-radius: 2px; background: var(--type); opacity: .75; }
.studio .neatlogs-page .nl-span-row time { flex: none; width: 54px; color: var(--text-3); font-family: var(--mono); font-size: 11px; text-align: right; }
.studio .neatlogs-page .nl-span.workflow > .nl-span-row time { color: var(--text-2); }
.studio .neatlogs-page .nl-span-panel { margin-top: 2px; margin-bottom: 8px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,.02); }
.studio .neatlogs-page .nl-span-details { display: grid; grid-template-columns: repeat(auto-fill,minmax(140px,1fr)); gap: 10px 18px; margin: 0; }
.studio .neatlogs-page .nl-span-details dt { color: var(--text-3); font-size: 9px; letter-spacing: .07em; text-transform: uppercase; }
.studio .neatlogs-page .nl-span-details dd { margin: 4px 0 0; color: var(--text-2); font-size: 11.5px; overflow-wrap: anywhere; }
.studio .neatlogs-page .nl-span-details dd.mono { font-family: var(--mono); font-size: 10.5px; }

/* Output */
.studio .neatlogs-page .nl-output { padding: 2px 2px 0; }
.studio .neatlogs-page .nl-output .prose { font-size: 13px; }
.studio .neatlogs-page .nl-verdict { margin: 14px 0 0; padding: 0; border: 1px solid var(--line); border-radius: 10px; list-style: none; overflow: hidden; }
.studio .neatlogs-page .nl-verdict li { display: flex; align-items: flex-start; gap: 11px; padding: 11px 13px; }
.studio .neatlogs-page .nl-verdict li + li { border-top: 1px solid var(--line); }
.studio .neatlogs-page .nl-verdict li > div { min-width: 0; }
.studio .neatlogs-page .nl-verdict p { margin-top: 5px; color: var(--text-2); font-size: 12px; line-height: 1.55; }
.studio .neatlogs-page .nl-lesson { margin-top: 14px; padding: 11px 13px; border: 1px solid rgba(232,196,90,.2); border-radius: 10px; background: var(--accent-soft); }
.studio .neatlogs-page .nl-lesson span { display: block; color: var(--accent); font-size: 9.5px; font-weight: 560; letter-spacing: .09em; text-transform: uppercase; }
.studio .neatlogs-page .nl-lesson p { margin-top: 5px; color: var(--text); font-size: 12.5px; line-height: 1.55; }

@keyframes nl-spin { to { transform: rotate(360deg); } }
@keyframes nl-pulse { 50% { opacity: .35; } }
@media (max-width: 1200px) {
  .studio .neatlogs-page .nl-tv-stats { grid-template-columns: repeat(4,minmax(0,1fr)); }
  .studio .neatlogs-page .nl-tv-stats > .nl-tv-session { grid-column: 1 / -1; padding-left: 22px; border-top: 1px solid var(--line); border-left: 0; }
  .studio .neatlogs-page .nl-span-bar { width: 80px; }
}
@media (max-width: 980px) {
  .studio .neatlogs-page.inspecting { overflow-y: auto; }
  .studio .neatlogs-page.inspecting .nl-focus { flex: none; grid-template-columns: 1fr; }
  .studio .neatlogs-page .nl-rail { max-height: 230px; }
  .studio .neatlogs-page .nl-tv-body { overflow: visible; }
  .studio .neatlogs-page .nl-span-bar { display: none; }
}
@media (max-width: 850px) {
  .studio .neatlogs-page { padding: 22px 18px 32px; }
  .studio .neatlogs-page .nl-kpis { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .studio .neatlogs-page .nl-kpis article:nth-child(3) { border-left: 0; }
  .studio .neatlogs-page .nl-kpis article:nth-child(n+3) { border-top: 1px solid var(--line); }
  .studio .neatlogs-page .nl-segments { width: 100%; margin-left: 0; overflow-x: auto; }
  .studio .neatlogs-page .nl-segments button { flex: 1; }
  .studio .neatlogs-page .nl-tv-stats { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .studio .neatlogs-page .nl-tv-stats > div:nth-child(3) { padding-left: 22px; border-left: 0; }
  .studio .neatlogs-page .nl-tv-stats > div:nth-child(n+3) { border-top: 1px solid var(--line); }
}
@media (max-width: 560px) {
  .studio .neatlogs-page .nl-header { align-items: flex-start; flex-direction: column; }
  .studio .neatlogs-page .nl-connection-detail { margin-left: 0; }
  .studio .neatlogs-page .nl-kpis { grid-template-columns: 1fr; }
  .studio .neatlogs-page .nl-kpis article + article { border-top: 1px solid var(--line); border-left: 0; }
  .studio .neatlogs-page .nl-browser-head { align-items: flex-start; flex-direction: column; padding-top: 12px; padding-bottom: 12px; }
  .studio .neatlogs-page .nl-search { max-width: none; }
  .studio .neatlogs-page :is(.nl-span-type, .nl-span-usage) { display: none; }
}

toolUseResult.content:
.studio .neatlogs-page {
  display: block;
  --nl-cyan: #78c5d6;
  --nl-cyan-soft: rgba(79, 184, 208, 0.12);
  --nl-workflow: #a78bfa;
  --nl-tool: #8b93ff;
  --nl-llm: #e8875a;
  --nl-sunk: #111215;
  --nl-tree-line: rgba(255, 255, 255, 0.11);
  padding: 30px 32px 42px;
}
.studio .neatlogs-page .nl-icon { fill: none; stroke: currentColor; stroke-width: 1.55; stroke-linecap: round; stroke-linejoin: round; }
.studio .neatlogs-page button, .studio .neatlogs-page input, .studio .neatlogs-page select { font: inherit; }
.studio .neatlogs-page .sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
.studio .neatlogs-page :is(button, input, select):focus-visible { outline: 2px solid var(--nl-cyan); outline-offset: 2px; }
.studio .neatlogs-page :is(.nl-header, .nl-heading, .nl-connection, .nl-browser-head, .nl-browser-head > div, .nl-toolbar) { display: flex; align-items: center; }
.studio .neatlogs-page .nl-header { justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.studio .neatlogs-page .nl-heading { gap: 12px; }
.studio .neatlogs-page .nl-mark { display: grid; place-items: center; width: 36px; height: 36px; border: 1px solid var(--line-strong); border-radius: 9px; background: linear-gradient(145deg, #25272d, #141519); box-shadow: 0 1px 0 rgba(255,255,255,.08) inset, 0 6px 18px rgba(0,0,0,.18); color: #f4f4f5; font-size: 16px; font-weight: 650; }
.studio .neatlogs-page .nl-heading h1 { font-size: 22px; font-weight: 620; letter-spacing: -.025em; }
.studio .neatlogs-page .nl-heading p { margin-top: 3px; color: var(--text-3); font-size: 12.5px; }
.studio .neatlogs-page .nl-connection { gap: 8px; height: 28px; padding: 0 10px; border: 1px solid var(--line); border-radius: 999px; background: var(--panel); color: var(--text-2); font-size: 11.5px; white-space: nowrap; }
.studio .neatlogs-page :is(.nl-connection i, .nl-trace-status i, .nl-outcome i) { flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--text-3); }
.studio .neatlogs-page .nl-connection.connected i { background: var(--good); }
.studio .neatlogs-page .nl-connection.unreachable i { background: var(--bad); }
.studio .neatlogs-page .nl-connection.loading i { background: var(--warn); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-connection-detail { margin: -7px 0 18px 48px; color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page .nl-connection-detail.unreachable { color: var(--bad-text); }

.studio .neatlogs-page .nl-kpis { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); margin-bottom: 16px; border: 1px solid var(--line); border-radius: 11px; background: var(--panel); overflow: hidden; }
.studio .neatlogs-page .nl-kpis article { min-width: 0; padding: 17px 18px 16px; }
.studio .neatlogs-page .nl-kpis article + article { border-left: 1px solid var(--line); }
.studio .neatlogs-page .nl-kpis span { display: block; color: var(--text-2); font-size: 11.5px; }
.studio .neatlogs-page .nl-kpis strong { display: block; margin: 6px 0 3px; color: var(--text); font-size: 22px; font-weight: 570; letter-spacing: -.025em; }
.studio .neatlogs-page .nl-kpis small { color: var(--text-3); font-size: 11px; }

.studio .neatlogs-page :is(.nl-browser, .nl-rail, .nl-trace-view) { min-width: 0; border: 1px solid var(--line); border-radius: 11px; background: var(--panel); overflow: hidden; }
.studio .neatlogs-page .nl-browser-head { justify-content: space-between; gap: 16px; min-height: 57px; padding: 0 14px 0 17px; border-bottom: 1px solid var(--line); }
.studio .neatlogs-page .nl-browser-head > div { gap: 8px; }
.studio .neatlogs-page .nl-browser-head h2 { font-size: 13.5px; font-weight: 600; }
.studio .neatlogs-page .nl-browser-head span { color: var(--text-3); font-size: 11.5px; }
.studio .neatlogs-page :is(.nl-check-button, .nl-button, .nl-lookup-message button, .nl-filter-empty button) { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 30px; padding: 0 10px; border: 1px solid var(--line-strong); border-radius: 7px; background: var(--raised); color: var(--text-2); font-size: 11.5px; }
.studio .neatlogs-page :is(.nl-check-button, .nl-button, .nl-lookup-message button, .nl-filter-empty button):hover:not(:disabled) { border-color: rgba(255,255,255,.18); background: var(--hover); color: var(--text); }
.studio .neatlogs-page .nl-check-button:disabled { opacity: .46; }
.studio .neatlogs-page .nl-check-button:not(:disabled) .nl-icon { color: var(--nl-cyan); }
.studio .neatlogs-page .nl-icon-button { display: inline-grid; flex: none; place-items: center; width: 30px; height: 30px; padding: 0; border: 1px solid var(--line-strong); border-radius: 7px; background: var(--raised); color: var(--text-2); }
.studio .neatlogs-page .nl-icon-button:hover:not(:disabled) { background: var(--hover); color: var(--text); }
.studio .neatlogs-page .nl-icon-button:disabled { opacity: .5; }
.studio .neatlogs-page .nl-icon-button:disabled .nl-icon { animation: nl-spin .8s linear infinite; }
.studio .neatlogs-page .nl-icon-button.small { width: 22px; height: 22px; border: 0; background: transparent; color: var(--text-3); }

.studio .neatlogs-page .nl-toolbar { flex-wrap: wrap; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--line); background: rgba(0,0,0,.08); }
.studio .neatlogs-page .nl-search { position: relative; display: flex; flex: 1 1 180px; align-items: center; min-width: 145px; max-width: 260px; color: var(--text-3); }
.studio .neatlogs-page .nl-search .nl-icon { position: absolute; left: 9px; pointer-events: none; }
.studio .neatlogs-page :is(.nl-search input, .nl-select select) { width: 100%; height: 30px; border: 1px solid var(--line); border-radius: 7px; background: var(--bg); color: var(--text); font-size: 11.5px; }
.studio .neatlogs-page .nl-search input { padding: 0 10px 0 30px; }
.studio .neatlogs-page .nl-search input::placeholder { color: var(--text-3); }
.studio .neatlogs-page .nl-select { position: relative; display: block; width: 126px; }
.studio .neatlogs-page .nl-select select { appearance: none; padding: 0 26px 0 9px; }
.studio .neatlogs-page .nl-select .nl-icon { position: absolute; top: 9px; right: 8px; color: var(--text-3); pointer-events: none; }
.studio .neatlogs-page .nl-segments { display: flex; gap: 2px; margin-left: auto; padding: 2px; border: 1px solid var(--line); border-radius: 7px; background: var(--bg); }
.studio .neatlogs-page .nl-segments button { height: 24px; padding: 0 8px; border: 0; border-radius: 5px; background: transparent; color: var(--text-3); font-size: 10.5px; }
.studio .neatlogs-page .nl-segments button:hover { color: var(--text); }
.studio .neatlogs-page .nl-segments button.active { background: var(--raised); color: var(--text); box-shadow: 0 1px 2px rgba(0,0,0,.25); }

.studio .neatlogs-page .nl-table-scroll { overflow-x: auto; }
.studio .neatlogs-page .nl-table { width: 100%; min-width: 650px; border-collapse: collapse; table-layout: fixed; }
.studio .neatlogs-page .nl-table th { height: 31px; padding: 0 12px; border-bottom: 1px solid var(--line); color: var(--text-3); font-size: 10px; font-weight: 520; letter-spacing: .035em; text-align: left; text-transform: uppercase; }
.studio .neatlogs-page .nl-table th:first-child { width: 35%; padding-left: 17px; }
.studio .neatlogs-page .nl-table th:nth-child(2) { width: 18%; }
.studio .neatlogs-page .nl-table th:nth-child(3) { width: 12%; }
.studio .neatlogs-page .nl-table th:nth-child(4) { width: 11%; }
.studio .neatlogs-page .nl-table th:nth-child(5) { width: 18%; }
.studio .neatlogs-page .nl-table th:nth-child(6) { width: 6%; }
.studio .neatlogs-page .nl-table :is(th,td).num { text-align: right; }
.studio .neatlogs-page .nl-table td { height: 48px; padding: 0 12px; border-bottom: 1px solid var(--line); color: var(--text-2); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.studio .neatlogs-page .nl-table tbody tr:last-child td { border-bottom: 0; }
.studio .neatlogs-page .nl-table tbody tr { cursor: pointer; transition: background .1s; }
.studio .neatlogs-page .nl-table tbody tr:hover { background: rgba(255,255,255,.025); }
.studio .neatlogs-page .nl-table td:first-child { padding: 0; }
.studio .neatlogs-page .nl-table td.nl-open { color: var(--text-3); opacity: 0; text-align: right; transition: opacity .12s, transform .12s; }
.studio .neatlogs-page .nl-table tbody tr:hover td.nl-open { color: var(--nl-cyan); opacity: 1; transform: translateX(2px); }
.studio .neatlogs-page .nl-session-button { display: flex; flex-direction: column; justify-content: center; width: 100%; height: 48px; padding: 0 12px 0 17px; border: 0; background: transparent; color: var(--text-3); font-size: 10.5px; text-align: left; overflow: hidden; }
.studio .neatlogs-page .nl-session-button:focus-visible { outline-offset: -3px; }
.studio .neatlogs-page .nl-session-name { display: block; width: 100%; margin-bottom: 2px; color: var(--text); font-size: 12px; font-weight: 540; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.studio .neatlogs-page .nl-model { color: var(--text-3); font-family: var(--mono); font-size: 10.5px; }
.studio .neatlogs-page :is(.nl-trace-status, .nl-outcome) { display: inline-flex; align-items: center; gap: 6px; color: var(--text-3); font-size: 10.5px; }
.studio .neatlogs-page .nl-trace-status.matched { color: var(--good-text); }
.studio .neatlogs-page .nl-trace-status.matched i { background: var(--good); }
.studio .neatlogs-page .nl-trace-status.error { color: var(--bad-text); }
.studio .neatlogs-page .nl-trace-status.error i { background: var(--bad); }
.studio .neatlogs-page .nl-trace-status.loading { color: var(--nl-cyan); }
.studio .neatlogs-page .nl-trace-status.loading i { background: var(--nl-cyan); animation: nl-pulse 1.5s ease-in-out infinite; }
.studio .neatlogs-page .nl-trace-status.none i { background: var(--warn); }
.studio .neatlogs-page .nl-trace-status.missing i { background: transparent; border: 1px solid var(--text-3); }

.studio .neatlogs-page .nl-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 34px 28px; text-align: center; }
.studio .neatlogs-page .nl-empty :is(h2,h3) { color: var(--text); font-size: 14px; font-weight: 580; }
.studio .neatlogs-page .nl-empty p { max-width: 245px; margin-top: 7px; color: var(--text-3); font-size: 11.5px; line-height: 1.55; }
.studio .neatlogs-page .nl-filter-empty { min-height: 250px; }
.studio .neatlogs-page .nl-filter-empty > .nl-icon { margin-bottom: 12px; color: var(--text-3); }
.studio .neatlogs-page .nl-filter-empty button { margin-top: 15px; }

