// Builds a preview fixture from the real mod records and real Neatlogs evidence.
require("dotenv").config({ path: require("path").join(__dirname, "..", ".env") });
const fs = require("fs");
const path = require("path");
const os = require("os");
const neatlogs = require("../electron/lib/neatlogs.cjs");

const dir = path.join(os.homedir(), ".benana", "studio");
const mods = fs.readdirSync(dir)
  .map((id) => path.join(dir, id, "mod.json"))
  .filter((f) => fs.existsSync(f))
  .map((f) => JSON.parse(fs.readFileSync(f, "utf8")))
  .map(({ feed, ...mod }) => mod)
  .sort((a, b) => b.createdAt - a.createdAt);

(async () => {
  const sessions = mods.flatMap((m) => [...m.sessions, ...m.attempts.flatMap((a) => a.sessions)]).filter((s) => s.sessionId);
  const evidence = {};
  for (const s of sessions.sort((a, b) => b.startedAt - a.startedAt).slice(0, 12)) {
    evidence[s.sessionId] = await neatlogs.evidence({ sessionId: s.sessionId });
    console.log(s.role, s.sessionId, evidence[s.sessionId].matched, evidence[s.sessionId].traces?.[0]?.spans?.length);
  }
  const partners = { neatlogs: await neatlogs.status() };
  fs.writeFileSync(path.join(__dirname, "nl-fixture.json"), JSON.stringify({ mods, evidence, partners }));
})();

