import React from "react";
import { createRoot } from "react-dom/client";
import fixture from "./nl-fixture.json";
import "../src/styles.css";
import "../src/components/studio/studio.css";

window.benana = {
  invoke: async (channel, payload) => {
    await new Promise((r) => setTimeout(r, 250));
    if (channel === "studio:partners") return { ok: true, data: fixture.partners };
    if (channel === "studio:evidence") return { ok: true, data: fixture.evidence[payload.sessionId] || { configured: true, matched: false, traces: [], matchReason: "Not in preview fixture." } };
    return { ok: false, error: `No preview stub for ${channel}` };
  },
  on: () => () => {},
};

const { default: NeatlogsPage } = await import("../src/components/studio/NeatlogsPage.jsx");
createRoot(document.getElementById("root")).render(
  <div className="studio"><main style={{ flex: 1, display: "flex", minWidth: 0 }}><NeatlogsPage mods={fixture.mods} onOpenMod={(id) => console.log("open", id)} /></main></div>,
);

